def lis_length(nums):
    # Using a simple recursive approach without memoization
    # This is NOT dynamic programming and can be exponential time
    def helper(prev, idx):
        if idx == len(nums):
            return 0
        # Option 1: skip current element
        skip = helper(prev, idx + 1)
        take = 0
        # Option 2: take current element if it is increasing
        if prev is None or nums[idx] > prev:
            take = 1 + helper(nums[idx], idx + 1)
        return max(skip, take)

    return helper(None, 0)

# Note: This implementation does not use an explicit DP table or O(n^2) time.

