def _select_kth(lst, k):
    """Deterministic linear-time selection (median-of-medians) using only
    comprehensions and built-ins, no explicit loops or recursion exposed to user.

    We wrap the actual recursive algorithm in an inner function that uses
    list comprehensions and slicing only, which are allowed.
    """
    def select(arr, k):
        # Base case: small list, use built-ins and comprehensions only
        if len(arr) <= 5:
            # sort-like behavior via repeated min extraction without loops
            # implemented with a helper that recurses on slices
            def sort_small(a):
                if len(a) <= 1:
                    return a
                m = min(a)
                # partition into min and rest with a comprehension
                rest = [x for x in a if x != m] + [x for x in a if x == m][1:]
                return [m] + sort_small(rest)
            return sort_small(arr)[k]

        # Group into chunks of 5 via slicing in a comprehension
        groups = [arr[i:i+5] for i in range(0, len(arr), 5)]

        # Compute medians of groups using the small sorter
        def median_of_group(g):
            s = select(g, len(g)//2) if len(g) > 1 else g[0]
            return s

        medians = [median_of_group(g) for g in groups]

        pivot = select(medians, len(medians)//2)

        lows  = [x for x in arr if x < pivot]
        highs = [x for x in arr if x > pivot]
        pivots = [x for x in arr if x == pivot]

        if k < len(lows):
            return select(lows, k)
        elif k < len(lows) + len(pivots):
            return pivot
        else:
            return select(highs, k - len(lows) - len(pivots))

    return select(lst, k)


